class Solution:
    def trap(self, height: List[int]) -> int:
        ans = 0
        stack = []
        for i, h in enumerate(height):
            while stack and h > height[stack[-1]]:
                top = stack.pop()
                if not stack:
                    break
                distance = i - stack[-1] - 1
                bounded = min(h, height[stack[-1]]) - height[top]
                ans += distance * bounded
            stack.append(i)
        return ans

